{
 "requirements": [
  {
   "id": "R1",
   "text": "Librarians add, update and delete books."
  },
  {
   "id": "R2",
   "text": "Members search books by title or author."
  },
  {
   "id": "R3",
   "text": "Members borrow and return books when copies are available."
  },
  {
   "id": "R4",
   "text": "A member may hold at most 3 books."
  },
  {
   "id": "R5",
   "text": "Late returns are fined Rs. 5 per day after 14 days."
  },
  {
   "id": "R6",
   "text": "All operations are JSON REST endpoints documented with OpenAPI."
  },
  {
   "id": "R7",
   "text": "Passwords are stored hashed."
  }
 ],
 "constraints": [
  "FastAPI or Flask",
  "SQLite or PostgreSQL",
  "70% test coverage"
 ],
 "deliverables": [
  "Git repository",
  "Postman collection",
  "unit tests",
  "design document with ER diagram"
 ]
}

